		if c >= utf8.RuneSelf {
			return strings.Map(unicode.ToLower, norm.NFKD.String(s))
		}
		if 'A' <= c && c <= 'Z' {
			hasUpper = true
			if pos < i {
				b.WriteString(s[pos:i])
			}
			c += 'a' - 'A'
			b.WriteByte(c)
			pos = i + 1
		}
	}
	if !hasUpper {
		return s
	}
	if pos < len(s) {
		b.WriteString(s[pos:])
	}
	return b.String()
}
